let palette;
let ease;
let grids;
let cam;
let offset, x_min, x_max, y_min, y_max;

function setup() {
	createCanvas(800, 800, WEBGL);
	colorMode(HSB, 360, 100, 100, 100);
	angleMode(DEGREES);
	smooth();

	offset = width / 8;
	x_min = offset;
	y_min = offset;
	x_max = width - offset;
	y_max = height - offset;

	palette = shuffle(random(colorScheme).colors.concat());
	grids = createGrid(x_min, y_min, x_max, y_max, 1 / 15, 1 / 5);
	ease = new p5.Ease();
	ortho(-width / 2, width / 2, -height / 2, height / 2, -5000, 5000);

	let a = 30;
	let b = -60;

	let cx = cos(a) * cos(b) * 150;
	let cy = sin(a) * cos(b) * 150;
	let cz = sin(b) * 150;

	cam = createCamera(cx, cy, cz);
	cam.setPosition(cx, cy, cz);
	cam.lookAt(0, 0, 0);

}

function draw() {
	blendMode(BLEND);
	background(0, 0, 20);

	if (frameCount % 250 == 0) {
		grids = createGrid(x_min, y_min, x_max, y_max, 1 / 10, 1 / 5);
		reverse(grids);
	}
	lights();

	scale(0.9);

	orbitControl();
	translate(-width / 2, -height / 2, 0);
	let n = 0;
	for (let grid of grids) {
		push();
		translate(grid.x + grid.w / 2, grid.y + grid.h / 2, 0);
		let v = ((frameCount / 2.5 + n++) / grids.length) % 1;
		rotate(ease.elasticOut(v * v) * 180 * (n % 2 == 0 ? -1 : 1));
		scale(ease.elasticInOut(v));
		rectMode(CENTER);
		fill(grid.color);
		stroke(0, 0, 20);
		box(grid.w, grid.h, grid.d);
		pop();
	}

	// print(grids);
	// noLoop();
}

function createGrid(x1, y1, x2, y2, min_ratio, max_ratio) {
	let grid = [];
	let isVertical = random() > 0.5;
	let x_size = x2 - x1;
	let y_size = y2 - y1;
	// random() > 0.5;
	let x, y, x_step, y_step;
	if (isVertical) {
		x = x1;
		let _wG_1 = 0; while ((x < x2) && ++_wG_1 < 20000) {
			palette = shuffle(random(colorScheme).colors.concat());

			x_step = random(x_size * min_ratio, x_size * max_ratio);
			if (x + x_step > x2) x_step = x2 - x;
			y = y1;
			let _wG_2 = 0; while ((y < y2) && ++_wG_2 < 20000) {
				y_step = random(y_size * min_ratio, y_size * max_ratio);
				if (y + y_step > y2) y_step = y2 - y;
				let obj = {
					x: x,
					y: y,
					w: x_step,
					h: y_step,
					d: 100,
					color: random(palette),
				};
				grid.push(obj);
				y += y_step;
			}
			x += x_step;
		}
	} else {
		y = y1;
		let _wG_3 = 0; while ((y < y2) && ++_wG_3 < 20000) {
			palette = shuffle(random(colorScheme).colors.concat());
			y_step = random(y_size * min_ratio, y_size * max_ratio);
			if (y + y_step > y2) y_step = y2 - y;
			x = x1;
			let _wG_4 = 0; while ((x < x2) && ++_wG_4 < 20000) {
				x_step = random(x_size * min_ratio, x_size * max_ratio);
				if (x + x_step > x2) x_step = x2 - x;
				let obj = {
					x: x,
					y: y,
					w: x_step,
					h: y_step,
					d: 100,
					color: random(palette),
				};
				grid.push(obj);
				x += x_step;
			}
			y += y_step;
		}
	}

	return grid;
}

